from pathlib import Path
import nbformat
from nbclient import NotebookClient
p=Path('/home/xueshuailin/CCC_Phe/Cellist_ST1_ST5_Joint_V3.ipynb');n=nbformat.read(p,4);tag='cellist_saved_joint_v1_k12'
source='''# 已保存的 ST1/ST5 联合 V3（现 V1）K=12：作者肿瘤边界 mask\nfrom pathlib import Path\nimport json, numpy as np, pandas as pd, anndata as ad, matplotlib.pyplot as plt\nfrom matplotlib.lines import Line2D\nfrom IPython.display import display\nW=Path('/data1/xueshuailin/CCC_Phe/workspace');base=W/'outputs/nsclc_zhencaiwei/ST1_ST5/v3_joint_K12'\nq=np.load(base/'predictions.npz'); labels=q['labels'];sid=q['sample_id'];ids=q['cell_ids'].astype(str)\na=ad.read_h5ad(W/'data/nsclc_zhencaiwei/ST1_ST5_joint_v3_input.h5ad',backed='r');xy=np.asarray(a.obsm['spatial']);assert np.array_equal(ids,a.obs_names.to_numpy(dtype=str));a.file.close()\nparts=[]\nfor s in ('ST1','ST5'):\n    a=ad.read_h5ad(W/f'data/nsclc_zhencaiwei/processed/{s}/{s}_counts.h5ad',backed='r')\n    assert np.array_equal(np.char.add(s+'::',a.obs_names.to_numpy(dtype=str)),ids[sid==({'ST1':0,'ST5':1}[s])]), f'{s} 行顺序不一致'\n    parts.append(a.obs['Tumor_boundary'].astype(str).to_numpy());a.file.close()\nboundary=np.concatenate(parts);bands=['Inner 1','Inner 2','Outer 1','Outer 2'];mask=np.isin(boundary,bands);pal=plt.get_cmap('tab20')(np.arange(12))\nfig,axes=plt.subplots(2,2,figsize=(11,9),layout='constrained')\nfor s in (0,1):\n    ix=np.flatnonzero(sid==s);order=np.random.default_rng(42).permutation(ix);ax=axes[0,s];ax.scatter(xy[order,0],xy[order,1],c=pal[labels[order]],s=.5,lw=0,rasterized=True);ax.set_title(f'{["ST1","ST5"][s]} · joint V3/V1 · K=12')\n    ax=axes[1,s];bg=order[~mask[order]];fg=order[mask[order]];ax.scatter(xy[bg,0],xy[bg,1],c='#d9d9d9',s=.45,lw=0,rasterized=True);ax.scatter(xy[fg,0],xy[fg,1],c=pal[labels[fg]],s=.7,lw=0,rasterized=True);ax.set_title(f'{["ST1","ST5"][s]} · author boundary mask · n={len(fg):,}')\n    for ax in axes[:,s]: ax.axis('off');ax.set_aspect('equal')\nfig.legend(handles=[Line2D([],[],marker='o',ls='',color=pal[j],label=f'N{j+1}',markersize=5) for j in range(12)]+[Line2D([],[],marker='o',ls='',color='#d9d9d9',label='Outside mask',markersize=5)],loc='outside lower center',ncol=7,fontsize=8,frameon=False)\nplt.show()\nprint('肿瘤边界 mask 使用作者 Tumor_boundary 的 Inner 1–2 和 Outer 1–2；其他区域灰色。')\nprint('各切片边界内的 niche 数量及比例：')\ncounts=pd.crosstab(pd.Series(sid[mask],name='Slice').map({0:'ST1',1:'ST5'}),pd.Series(labels[mask]+1,name='Niche')).reindex(index=['ST1','ST5'],columns=range(1,13),fill_value=0)\ndisplay(counts);display((counts.div(counts.sum(axis=1),axis=0)*100).round(1))\nprint('分别列出边界内外各层的 niche 比例（%）：')\nband=pd.crosstab([pd.Series(sid[mask],name='Slice').map({0:'ST1',1:'ST5'}),pd.Series(boundary[mask],name='Boundary')],pd.Series(labels[mask]+1,name='Niche')).reindex(columns=range(1,13),fill_value=0)\ndisplay((band.div(band.sum(axis=1),axis=0)*100).round(1))\nmeta=json.loads((base/'complete.json').read_text());print('K=12 复用已有联合 h，不重新训练编码器；聚类收敛：',meta['converged'],'，迭代次数：',meta['iterations'])\n'''
cell=nbformat.v4.new_code_cell(source,metadata={'tags':[tag]});run=nbformat.v4.new_notebook(cells=[cell],metadata=n.metadata);NotebookClient(run,timeout=300,kernel_name='cccphe').execute(cwd=str(p.parent));latest=nbformat.read(p,4);found=[i for i,c in enumerate(latest.cells) if tag in c.get('metadata',{}).get('tags',[])];
if found: latest.cells[found[0]]=run.cells[0]
else: latest.cells.append(run.cells[0])
nbformat.write(latest,p);print('updated K12 cell')
